import raw from "@/lib/data/metagenics/catalog.json"
import type { ContentBlock, ProductQA, Rating, SupplementFacts, Variant } from "@/types"

/** Shape of catalog.json, generated by scripts/import-metagenics.mjs (also used for products read from Medusa). */
export interface CatalogProduct {
  slug: string
  /** Medusa product id, when the product comes from the backend */
  medusaId?: string
  name: string
  subtitle?: string
  summary?: string
  sourceUrl: string
  image?: string
  categories: string[]
  isBundle: boolean
  productLine?: string
  form: string
  rating?: Rating
  variants: Variant[]
  description: ContentBlock[]
  supplementFacts?: SupplementFacts | null
  directions?: string
  storage?: string
  cautions?: string
  warnings?: string
  faq: ProductQA[]
  related: string[]
}

export interface CatalogFile {
  source: { repo: string; batch: string; products: number }
  categories: { slug: string; name: string; sourceUrl: string; count: number }[]
  products: CatalogProduct[]
}

/**
 * The generated catalog. The storefront reads **products** from the Medusa backend
 * (lib/data/metagenics/remote.ts); this file is still the source for the backend import
 * and for the store's taxonomy (category names, product lines) used in the header/footer.
 */
export const catalog = raw as unknown as CatalogFile
